INSERT INTO `universities` VALUES (3,'taylor-s-university','TAYLORS','{\"en\": \"Taylor\'s University\", \"ms\": \"Taylor\'s University\", \"zh-CN\": \"泰莱大学\", \"zh-TW\": \"泰莱大学\"}','Taylor\'s','https://upload.wikimedia.org/wikipedia/en/thumb/a/a6/Taylor%27s_University_Logo.svg/200px-Taylor%27s_University_Logo.svg.png','https://images.unsplash.com/photo-1568792923760-d70635a89fdc?w=800&h=500&fit=crop','#8B0000',272,27,'{\"en\": \"雪兰莪·双威城\", \"ms\": \"雪兰莪·双威城\", \"zh-CN\": \"雪兰莪·双威城\", \"zh-TW\": \"雪兰莪·双威城\"}','{\"en\": \"雪兰莪州\", \"ms\": \"雪兰莪州\", \"zh-CN\": \"雪兰莪州\", \"zh-TW\": \"雪兰莪州\"}','private','comprehensive',1969,16000,4500,1,'{\"en\": \"泰莱大学（Taylor\'s University）是马来西亚私立大学综合排名最高的院校，QS WUR 2027 #272，QS亚洲排名第41。位于雪兰莪双威城，以酒店旅游管理（QS学科全球Top 50）、商科、法律、建筑、医学和设计著称。泰莱提供与澳洲、英国、美国顶尖院校的学分转移和双学位项目。注意：自2025年7月起对国际生加征6% SST服务税，学费已含税。\", \"ms\": \"泰莱大学（Taylor\'s University）是马来西亚私立大学综合排名最高的院校，QS WUR 2027 #272，QS亚洲排名第41。位于雪兰莪双威城，以酒店旅游管理（QS学科全球Top 50）、商科、法律、建筑、医学和设计著称。泰莱提供与澳洲、英国、美国顶尖院校的学分转移和双学位项目。注意：自2025年7月起对国际生加征6% SST服务税，学费已含税。\", \"zh-CN\": \"泰莱大学（Taylor\'s University）是马来西亚私立大学综合排名最高的院校，QS WUR 2027 #272，QS亚洲排名第41。位于雪兰莪双威城，以酒店旅游管理（QS学科全球Top 50）、商科、法律、建筑、医学和设计著称。泰莱提供与澳洲、英国、美国顶尖院校的学分转移和双学位项目。注意：自2025年7月起对国际生加征6% SST服务税，学费已含税。\", \"zh-TW\": \"泰莱大学（Taylor\'s University）是马来西亚私立大学综合排名最高的院校，QS WUR 2027 #272，QS亚洲排名第41。位于雪兰莪双威城，以酒店旅游管理（QS学科全球Top 50）、商科、法律、建筑、医学和设计著称。泰莱提供与澳洲、英国、美国顶尖院校的学分转移和双学位项目。注意：自2025年7月起对国际生加征6% SST服务税，学费已含税。\"}','https://university.taylors.edu.my','intl.enquiry@taylors.edu.my','Taylor\'s University','https://university.taylors.edu.my','','','','',NULL,NULL,NULL,NULL,'{\"rankings\": {\"qsWorld\": {\"name\": \"QS World University Rankings\", \"year\": 2027, \"qsCity\": \"Kuala Lumpur\", \"status\": \"ranked\", \"context\": \"malaysia-institution\", \"qsTitle\": \"Taylor\'s University\", \"rankSort\": 272, \"qsCountry\": \"Malaysia\", \"sourceUrl\": \"https://www.topuniversities.com/rankings/endpoint?nid=4153156&page=0&items_per_page=100&tab=indicators&region=&countri